const formulaire = document.querySelector("#demande");
const nom = document.querySelector("#nom");
const atelier = document.querySelector("#atelier");
const retour = document.querySelector("#retour");
formulaire.addEventListener("submit", function(evenement) {
  evenement.preventDefault();
  const valeur = nom.value.trim();
  if (valeur === "") { retour.textContent = "Prénom requis."; return; }
  if (atelier.value === "") { retour.textContent = "Choisis un atelier."; return; }
  retour.textContent = valeur + " · " + atelier.value + " · démonstration";
});

